1	//! 无状态快照差异（diff）与双向回放（apply）的核心逻辑。
2	//!
3	//! 本模块只接收和返回 `serde_json::Value`，不感知 HTTP；
4	//! HTTP 层仅负责 JSON 解析与状态码映射。
5	
6	use serde_json::{Map, Number, Value};
7	use std::collections::BTreeMap;
8	
9	/// 业务错误。`status` 为 HTTP 状态码，`path` 用 RFC 6901 风格定位请求体中的出错字段。
10	#[derive(Debug)]
11	pub struct ApiError {
12	    pub status: u16,
13	    pub code: &'static str,
14	    pub message: String,
15	    pub path: String,
16	}
17	
18	impl ApiError {
19	    pub fn bad_request(message: impl Into<String>, path: impl Into<String>) -> Self {
20	        Self {
21	            status: 400,
22	            code: "bad_request",
23	            message: message.into(),
24	            path: path.into(),
25	        }
26	    }
27	
28	    pub fn conflict(message: impl Into<String>, path: impl Into<String>) -> Self {
29	        Self {
30	            status: 409,
31	            code: "conflict",
32	            message: message.into(),
33	            path: path.into(),
34	        }
35	    }
36	}
37	
38	/// 对象字段差异。`old`/`new` 为 `None` 表示该侧字段缺失（与 JSON null 严格区分）。
39	#[derive(Debug, Clone, PartialEq)]
40	struct Field {
41	    path: String,
42	    old: Option<Value>,
43	    new: Option<Value>,
44	}
45	
46	#[derive(Debug)]
47	enum Change {
48	    Add { id: String, value: Value },
49	    Remove { id: String, value: Value },
50	    Update { id: String, fields: Vec<Field> },
51	}
52	
53	impl Change {
54	    fn id(&self) -> &str {
55	        match self {
56	            Change::Add { id, .. } | Change::Remove { id, .. } | Change::Update { id, .. } => id,
57	        }
58	    }
59	}
60	
61	/// 计算 before → after 的差异，返回 `{"changes": [...]}`。
62	pub fn diff(request: &Value) -> Result<Value, ApiError> {
63	    let obj = request_object(request)?;
64	    let before = parse_rows(obj.get("before"), "/before")?;
65	    let after = parse_rows(obj.get("after"), "/after")?;
66	
67	    // before / after 均已按 id 升序，归并遍历即得按 id 升序的 changes。
68	    let mut changes = Vec::new();
69	    let mut i = 0;
70	    let mut j = 0;
71	    while i < before.len() || j < after.len() {
72	        match (before.get(i), after.get(j)) {
73	            (Some(b), Some(a)) => match b.0.cmp(&a.0) {
74	                std::cmp::Ordering::Less => {
75	                    changes.push(row_change(&b.0, "remove", &b.1));
76	                    i += 1;
77	                }
78	                std::cmp::Ordering::Greater => {
79	                    changes.push(row_change(&a.0, "add", &a.1));
80	                    j += 1;
81	                }
82	                std::cmp::Ordering::Equal => {
83	                    let mut fields = Vec::new();
84	                    diff_value("", Some(&b.1), Some(&a.1), &mut fields);
85	                    if !fields.is_empty() {
86	                        fields.sort_by(|x, y| x.path.cmp(&y.path));
87	                        changes.push(update_change(&a.0, &fields));
88	                    }
89	                    i += 1;
90	                    j += 1;
91	                }
92	            },
93	            (Some(b), None) => {
94	                changes.push(row_change(&b.0, "remove", &b.1));
95	                i += 1;
96	            }
97	            (None, Some(a)) => {
98	                changes.push(row_change(&a.0, "add", &a.1));
99	                j += 1;
100	            }
101	            (None, None) => break,
102	        }
103	    }
104	
105	    let mut root = Map::new();
106	    root.insert("changes".to_owned(), Value::Array(changes));
107	    Ok(Value::Object(root))
108	}
109	
110	/// 校验并应用变更，返回按 id 升序的 `{"rows": [...]}`。
111	/// 正向（forward）应用 old→new，反向（reverse）还原 new→old。
112	/// 任一校验失败即整体拒绝，不部分应用。
113	pub fn apply(request: &Value) -> Result<Value, ApiError> {
114	    let obj = request_object(request)?;
115	    let rows = parse_rows(obj.get("rows"), "/rows")?;
116	
117	    let direction_path = "/direction";
118	    let direction = obj
119	        .get("direction")
120	        .and_then(Value::as_str)
121	        .filter(|d| *d == "forward" || *d == "reverse")
122	        .ok_or_else(|| {
123	            ApiError::bad_request(
124	                "direction must be \"forward\" or \"reverse\"",
125	                direction_path,
126	            )
127	        })?;
128	    let reverse = direction == "reverse";
129	
130	    let changes_value = obj
131	        .get("changes")
132	        .ok_or_else(|| ApiError::bad_request("missing required field", "/changes"))?;
133	    let changes_array = changes_value
134	        .as_array()
135	        .ok_or_else(|| ApiError::bad_request("changes must be an array", "/changes"))?;
136	    let mut changes = Vec::with_capacity(changes_array.len());
137	    for (i, item) in changes_array.iter().enumerate() {
138	        changes.push(parse_change(item, &format!("/changes/{i}"))?);
139	    }
140	    for (i, change) in changes.iter().enumerate() {
141	        if changes[..i].iter().any(|c| c.id() == change.id()) {
142	            return Err(ApiError::bad_request(
143	                format!("duplicate change for row id {:?}", change.id()),
144	                format!("/changes/{i}/id"),
145	            ));
146	        }
147	    }
148	
149	    // 每个 change 作用于不同的行，因此可以全部基于原始状态校验后再统一应用。
150	    let mut rows_map: BTreeMap<String, Value> = rows.into_iter().collect();
151	    for (i, change) in changes.iter().enumerate() {
152	        validate_change(&rows_map, change, reverse, &format!("/changes/{i}"))?;
153	    }
154	    for change in &changes {
155	        apply_change(&mut rows_map, change, reverse);
156	    }
157	
158	    let rows_json = rows_map
159	        .into_iter()
160	        .map(|(id, values)| {
161	            let mut m = Map::new();
162	            m.insert("id".to_owned(), Value::String(id));
163	            m.insert("values".to_owned(), values);
164	            Value::Object(m)
165	        })
166	        .collect();
167	    let mut root = Map::new();
168	    root.insert("rows".to_owned(), Value::Array(rows_json));
169	    Ok(Value::Object(root))
170	}
171	
172	fn request_object(request: &Value) -> Result<&Map<String, Value>, ApiError> {
173	    request
174	        .as_object()
175	        .ok_or_else(|| ApiError::bad_request("request body must be a JSON object", ""))
176	}
177	
178	/// 解析并校验行数组：id 为非空唯一字符串，values 为对象。返回按 id 升序的行。
179	fn parse_rows(value: Option<&Value>, path: &str) -> Result<Vec<(String, Value)>, ApiError> {
180	    let value = value.ok_or_else(|| ApiError::bad_request("missing required field", path))?;
181	    let array = value
182	        .as_array()
183	        .ok_or_else(|| ApiError::bad_request("expected an array of rows", path))?;
184	
185	    let mut rows = Vec::with_capacity(array.len());
186	    for (i, item) in array.iter().enumerate() {
187	        let item_path = format!("{path}/{i}");
188	        let obj = item
189	            .as_object()
190	            .ok_or_else(|| ApiError::bad_request("row must be an object", &item_path))?;
191	        let id_path = format!("{item_path}/id");
192	        let id = obj
193	            .get("id")
194	            .and_then(Value::as_str)
195	            .ok_or_else(|| ApiError::bad_request("row id must be a string", &id_path))?;
196	        if id.is_empty() {
197	            return Err(ApiError::bad_request("row id must be non-empty", &id_path));
198	        }
199	        let values_path = format!("{item_path}/values");
200	        let values = obj
201	            .get("values")
202	            .ok_or_else(|| ApiError::bad_request("missing required field", &values_path))?;
203	        if !values.is_object() {
204	            return Err(ApiError::bad_request(
205	                "row values must be an object",
206	                &values_path,
207	            ));
208	        }
209	        rows.push((id.to_owned(), values.clone()));
210	    }
211	
212	    rows.sort_by(|a, b| a.0.cmp(&b.0));
213	    for pair in rows.windows(2) {
214	        if pair[0].0 == pair[1].0 {
215	            return Err(ApiError::bad_request(
216	                format!("duplicate row id {:?}", pair[0].0),
217	                path,
218	            ));
219	        }
220	    }
221	    Ok(rows)
222	}
223	
224	fn parse_change(value: &Value, path: &str) -> Result<Change, ApiError> {
225	    let obj = value
226	        .as_object()
227	        .ok_or_else(|| ApiError::bad_request("change must be an object", path))?;
228	
229	    let id_path = format!("{path}/id");
230	    let id = obj
231	        .get("id")
232	        .and_then(Value::as_str)
233	        .ok_or_else(|| ApiError::bad_request("change id must be a string", &id_path))?;
234	    if id.is_empty() {
235	        return Err(ApiError::bad_request("change id must be non-empty", &id_path));
236	    }
237	
238	    let op_path = format!("{path}/op");
239	    let op = obj
240	        .get("op")
241	        .and_then(Value::as_str)
242	        .ok_or_else(|| ApiError::bad_request("change op must be a string", &op_path))?;
243	
244	    match op {
245	        "add" | "remove" => {
246	            let value_path = format!("{path}/value");
247	            let row_value = obj
248	                .get("value")
249	                .ok_or_else(|| ApiError::bad_request("missing required field", &value_path))?;
250	            if !row_value.is_object() {
251	                return Err(ApiError::bad_request(
252	                    "change value must be an object",
253	                    &value_path,
254	                ));
255	            }
256	            let id = id.to_owned();
257	            let value = row_value.clone();
258	            Ok(if op == "add" {
259	                Change::Add { id, value }
260	            } else {
261	                Change::Remove { id, value }
262	            })
263	        }
264	        "update" => {
265	            let fields_path = format!("{path}/fields");
266	            let fields_value = obj
267	                .get("fields")
268	                .ok_or_else(|| ApiError::bad_request("missing required field", &fields_path))?;
269	            let fields_array = fields_value
270	                .as_array()
271	                .ok_or_else(|| ApiError::bad_request("fields must be an array", &fields_path))?;
272	
273	            let mut fields = Vec::with_capacity(fields_array.len());
274	            for (i, item) in fields_array.iter().enumerate() {
275	                fields.push(parse_field(item, &format!("{fields_path}/{i}"))?);
276	            }
277	            for (i, field) in fields.iter().enumerate() {
278	                if fields[..i].iter().any(|f| f.path == field.path) {
279	                    return Err(ApiError::bad_request(
280	                        format!("duplicate field path {:?}", field.path),
281	                        format!("{fields_path}/{i}/path"),
282	                    ));
283	                }
284	            }
285	            Ok(Change::Update {
286	                id: id.to_owned(),
287	                fields,
288	            })
289	        }
290	        _ => Err(ApiError::bad_request(
291	            format!("unknown change op {op:?}"),
292	            &op_path,
293	        )),
294	    }
295	}
296	
297	fn parse_field(value: &Value, path: &str) -> Result<Field, ApiError> {
298	    let obj = value
299	        .as_object()
300	        .ok_or_else(|| ApiError::bad_request("field must be an object", path))?;
301	
302	    let pointer_path = format!("{path}/path");
303	    let pointer = obj
304	        .get("path")
305	        .and_then(Value::as_str)
306	        .ok_or_else(|| ApiError::bad_request("field path must be a string", &pointer_path))?;
307	    let segments = parse_pointer(pointer).ok_or_else(|| {
308	        ApiError::bad_request(
309	            "field path must be a non-empty RFC 6901 JSON Pointer",
310	            &pointer_path,
311	        )
312	    })?;
313	
314	    let old = obj.get("old").cloned();
315	    let new = obj.get("new").cloned();
316	    if old.is_none() && new.is_none() {
317	        return Err(ApiError::bad_request(
318	            "field must contain old and/or new",
319	            path,
320	        ));
321	    }
322	    // 归一化为规范转义形式，保证路径唯一性比较不受等价写法影响。
323	    Ok(Field {
324	        path: canonical_pointer(&segments),
325	        old,
326	        new,
327	    })
328	}
329	
330	/// 递归比较两个值，把差异追加到 `out`。数组与非对象值整体比较。
331	fn diff_value(path: &str, old: Option<&Value>, new: Option<&Value>, out: &mut Vec<Field>) {
332	    match (old, new) {
333	        (Some(Value::Object(old_obj)), Some(Value::Object(new_obj))) => {
334	            for (key, old_value) in old_obj {
335	                let child_path = format!("{path}/{}", escape_segment(key));
336	                match new_obj.get(key) {
337	                    Some(new_value) => {
338	                        diff_value(&child_path, Some(old_value), Some(new_value), out)
339	                    }
340	                    None => out.push(Field {
341	                        path: child_path,
342	                        old: Some(old_value.clone()),
343	                        new: None,
344	                    }),
345	                }
346	            }
347	            for (key, new_value) in new_obj {
348	                if !old_obj.contains_key(key) {
349	                    out.push(Field {
350	                        path: format!("{path}/{}", escape_segment(key)),
351	                        old: None,
352	                        new: Some(new_value.clone()),
353	                    });
354	                }
355	            }
356	        }
357	        _ => {
358	            let equal = match (old, new) {
359	                (Some(a), Some(b)) => json_eq(a, b),
360	                (None, None) => true,
361	                _ => false,
362	            };
363	            if !equal {
364	                out.push(Field {
365	                    path: path.to_owned(),
366	                    old: old.cloned(),
367	                    new: new.cloned(),
368	                });
369	            }
370	        }
371	    }
372	}
373	
374	/// 递归相等：对象键序无关，数字按数学值比较（如 1 与 1.0 相等）。
375	fn json_eq(a: &Value, b: &Value) -> bool {
376	    match (a, b) {
377	        (Value::Number(x), Value::Number(y)) => number_eq(x, y),
378	        (Value::Array(x), Value::Array(y)) => {
379	            x.len() == y.len() && x.iter().zip(y.iter()).all(|(u, v)| json_eq(u, v))
380	        }
381	        (Value::Object(x), Value::Object(y)) => {
382	            x.len() == y.len()
383	                && x.iter()
384	                    .all(|(k, v)| y.get(k).is_some_and(|w| json_eq(v, w)))
385	        }
386	        _ => a == b,
387	    }
388	}
389	
390	fn number_eq(a: &Number, b: &Number) -> bool {
391	    if a.is_f64() || b.is_f64() {
392	        a.as_f64() == b.as_f64()
393	    } else {
394	        // 两侧均为整数时直接比较，避免浮点精度损失。
395	        a == b
396	    }
397	}
398	
399	fn escape_segment(segment: &str) -> String {
400	    segment.replace('~', "~0").replace('/', "~1")
401	}
402	
403	/// 解析 RFC 6901 JSON Pointer。空指针（指向整个文档）在此不允许，返回 None。
404	fn parse_pointer(path: &str) -> Option<Vec<String>> {
405	    if path.is_empty() || !path.starts_with('/') {
406	        return None;
407	    }
408	    let mut segments = Vec::new();
409	    for raw in path[1..].split('/') {
410	        let mut segment = String::with_capacity(raw.len());
411	        let mut chars = raw.chars();
412	        while let Some(c) = chars.next() {
413	            if c == '~' {
414	                match chars.next() {
415	                    Some('0') => segment.push('~'),
416	                    Some('1') => segment.push('/'),
417	                    _ => return None,
418	                }
419	            } else {
420	                segment.push(c);
421	            }
422	        }
423	        segments.push(segment);
424	    }
425	    Some(segments)
426	}
427	
428	fn canonical_pointer(segments: &[String]) -> String {
429	    let mut out = String::new();
430	    for segment in segments {
431	        out.push('/');
432	        out.push_str(&escape_segment(segment));
433	    }
434	    out
435	}
436	
437	fn get_path<'a>(root: &'a Value, segments: &[String]) -> Option<&'a Value> {
438	    let mut current = root;
439	    for segment in segments {
440	        current = current.as_object()?.get(segment)?;
441	    }
442	    Some(current)
443	}
444	
445	/// 除最后一段外，路径沿途必须都是已存在的对象。
446	fn parent_is_object(root: &Value, segments: &[String]) -> bool {
447	    let mut current = root;
448	    for segment in &segments[..segments.len() - 1] {
449	        match current.as_object().and_then(|m| m.get(segment)) {
450	            Some(next) if next.is_object() => current = next,
451	            _ => return false,
452	        }
453	    }
454	    true
455	}
456	
457	fn set_path(root: &mut Value, segments: &[String], value: Value) {
458	    let mut current = root;
459	    for segment in &segments[..segments.len() - 1] {
460	        current = match current.as_object_mut().and_then(|m| m.get_mut(segment)) {
461	            Some(next) if next.is_object() => next,
462	            _ => unreachable!("parent path validated before apply"),
463	        };
464	    }
465	    if let Some(obj) = current.as_object_mut() {
466	        obj.insert(segments[segments.len() - 1].clone(), value);
467	    }
468	}
469	
470	fn remove_path(root: &mut Value, segments: &[String]) {
471	    let mut current = root;
472	    for segment in &segments[..segments.len() - 1] {
473	        current = match current.as_object_mut().and_then(|m| m.get_mut(segment)) {
474	            Some(next) if next.is_object() => next,
475	            _ => return,
476	        };
477	    }
478	    if let Some(obj) = current.as_object_mut() {
479	        obj.remove(&segments[segments.len() - 1]);
480	    }
481	}
482	
483	fn row_change(id: &str, op: &str, value: &Value) -> Value {
484	    let mut m = Map::new();
485	    m.insert("id".to_owned(), Value::String(id.to_owned()));
486	    m.insert("op".to_owned(), Value::String(op.to_owned()));
487	    m.insert("value".to_owned(), value.clone());
488	    Value::Object(m)
489	}
490	
491	fn update_change(id: &str, fields: &[Field]) -> Value {
492	    let mut m = Map::new();
493	    m.insert("id".to_owned(), Value::String(id.to_owned()));
494	    m.insert("op".to_owned(), Value::String("update".to_owned()));
495	    m.insert(
496	        "fields".to_owned(),
497	        Value::Array(fields.iter().map(field_json).collect()),
498	    );
499	    Value::Object(m)
500	}
501	
502	fn field_json(field: &Field) -> Value {
503	    let mut m = Map::new();
504	    m.insert("path".to_owned(), Value::String(field.path.clone()));
505	    if let Some(old) = &field.old {
506	        m.insert("old".to_owned(), old.clone());
507	    }
508	    if let Some(new) = &field.new {
509	        m.insert("new".to_owned(), new.clone());
510	    }
511	    Value::Object(m)
512	}
513	
514	fn validate_change(
515	    rows: &BTreeMap<String, Value>,
516	    change: &Change,
517	    reverse: bool,
518	    change_path: &str,
519	) -> Result<(), ApiError> {
520	    match change {
521	        // 正向 add：行必须不存在；反向 add：行必须存在且内容等于 value。
522	        Change::Add { id, value } => {
523	            if reverse {
524	                expect_row(rows, id, value, change_path)
525	            } else if rows.contains_key(id) {
526	                Err(ApiError::conflict(
527	                    format!("row {id:?} already exists"),
528	                    format!("{change_path}/id"),
529	                ))
530	            } else {
531	                Ok(())
532	            }
533	        }
534	        // 正向 remove：行必须存在且内容等于 value；反向 remove：行必须不存在。
535	        Change::Remove { id, value } => {
536	            if reverse {
537	                if rows.contains_key(id) {
538	                    Err(ApiError::conflict(
539	                        format!("row {id:?} already exists"),
540	                        format!("{change_path}/id"),
541	                    ))
542	                } else {
543	                    Ok(())
544	                }
545	            } else {
546	                expect_row(rows, id, value, change_path)
547	            }
548	        }
549	        Change::Update { id, fields } => {
550	            let row = rows.get(id).ok_or_else(|| {
551	                ApiError::conflict(
552	                    format!("row {id:?} does not exist"),
553	                    format!("{change_path}/id"),
554	                )
555	            })?;
556	            for (i, field) in fields.iter().enumerate() {
557	                validate_field(row, field, reverse, &format!("{change_path}/fields/{i}"))?;
558	            }
559	            Ok(())
560	        }
561	    }
562	}
563	
564	fn expect_row(
565	    rows: &BTreeMap<String, Value>,
566	    id: &str,
567	    value: &Value,
568	    change_path: &str,
569	) -> Result<(), ApiError> {
570	    match rows.get(id) {
571	        None => Err(ApiError::conflict(
572	            format!("row {id:?} does not exist"),
573	            format!("{change_path}/id"),
574	        )),
575	        Some(current) if !json_eq(current, value) => Err(ApiError::conflict(
576	            format!("row {id:?} values do not match expected value"),
577	            format!("{change_path}/value"),
578	        )),
579	        _ => Ok(()),
580	    }
581	}
582	
583	fn validate_field(
584	    row: &Value,
585	    field: &Field,
586	    reverse: bool,
587	    field_path: &str,
588	) -> Result<(), ApiError> {
589	    let segments = parse_pointer(&field.path).expect("field path validated at parse time");
590	    // 校验的一侧：正向看 old，反向看 new。None 表示该路径必须缺失（与 null 区分）。
591	    let expected = if reverse { &field.new } else { &field.old };
592	    let current = get_path(row, &segments);
593	    let side = if reverse { "new" } else { "old" };
594	    match (expected, current) {
595	        (None, None) => {}
596	        (Some(e), Some(c)) if json_eq(e, c) => {}
597	        (None, Some(_)) => {
598	            return Err(ApiError::conflict(
599	                "expected field to be absent but it exists",
600	                field_path.to_owned(),
601	            ));
602	        }
603	        (Some(_), None) => {
604	            return Err(ApiError::conflict(
605	                "expected value but field is missing",
606	                format!("{field_path}/{side}"),
607	            ));
608	        }
609	        (Some(_), Some(_)) => {
610	            return Err(ApiError::conflict(
611	                "field value does not match expected value",
612	                format!("{field_path}/{side}"),
613	            ));
614	        }
615	    }
616	    // 写入的一侧需要父路径存在且为对象。
617	    let target = if reverse { &field.old } else { &field.new };
618	    if target.is_some() && !parent_is_object(row, &segments) {
619	        return Err(ApiError::conflict(
620	            "parent path does not exist or is not an object",
621	            format!("{field_path}/path"),
622	        ));
623	    }
624	    Ok(())
625	}
626	
627	fn apply_change(rows: &mut BTreeMap<String, Value>, change: &Change, reverse: bool) {
628	    match change {
629	        Change::Add { id, value } => {
630	            if reverse {
631	                rows.remove(id);
632	            } else {
633	                rows.insert(id.clone(), value.clone());
634	            }
635	        }
636	        Change::Remove { id, value } => {
637	            if reverse {
638	                rows.insert(id.clone(), value.clone());
639	            } else {
640	                rows.remove(id);
641	            }
642	        }
643	        Change::Update { id, fields } => {
644	            let row = rows.get_mut(id).expect("row existence validated before apply");
645	            for field in fields {
646	                let segments =
647	                    parse_pointer(&field.path).expect("field path validated at parse time");
648	                let target = if reverse { &field.old } else { &field.new };
649	                match target {
650	                    Some(value) => set_path(row, &segments, value.clone()),
651	                    None => remove_path(row, &segments),
652	                }
653	            }
654	        }
655	    }
656	}
657	
